sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    //データ変換　　YYYY-MM-DD HH:mm:ss→タイムスタンプ
    function dateTimeStringToTimestamp(dateTimeString) {
        const date = new Date(dateTimeString);
        const timestamp = date.getTime();
        return timestamp;
    }
    //予定情報からデータを取得
    var event_list = api.data.look_up_multiple_records_1.results;
    //ユーザー検索欄の入力データを取得
    var user_name = api.state.user_name;
    //ログインしているユーザー情報を取得
    var user_event_list = api.data.look_up_multiple_records_4.results;
    //ログインしているユーザー名を取得
    var user_login_name = user_event_list[0].user_name.displayValue;
    var user_group = user_event_list[0].department.displayValue;
    //ログ結果を取得
    console.log("event_data:", event_list);
    console.log("user_name:", user_name);
    var str = "[";
    //予定情報からデータを繰り返し
    for (var i = 0; i < event_list.length; i++) {
        //ユーザー検索欄の入力値と予定情報の項目「参加者」情報が一致する場合、JSON情報を組み合わせ
        if ((user_name == event_list[i].u_kanren_shien_taishosha.displayValue && event_list[i].u_gurupu.displayValue == user_group)) {
            //カレンダーの予定情報を設定
            //背景色をつけて
            var bgColor = "nds-yellow";
            //内容欄を設定
            var description = "参加者:" + event_list[i].u_kanren_shien_taishosha.displayValue;
            //予定情報の開始時間
            var start = event_list[i].u_kaishibi.value + " " + event_list[i].u_kaishi_jikan.value;
            //予定情報の終了時間
            var end = event_list[i].u_shuryobi.value + " " + event_list[i].u_shuryo_jikan.value;
            //予定情報の開始時間変換
            var startTime = dateTimeStringToTimestamp(start);
            //予定情報の終了時間変換
            var endTime = dateTimeStringToTimestamp(end);

            if (event_list[i].u_yotei_shubetsu.value == 1) {
                var group = "groupIT";
            } else {
                var group = event_list[i].u_gurupu.value;
            }
            //Json情報を組み合わせ
            str += '{' + '"bgColor":' + '"' + bgColor + '",' +
                '"description":' + '"' + description + '",' +
                '"end":' + '"' + end + '",' +
                '"endMS":' + endTime + ',' +
                '"group":' + '"' + group + '",' +
                '"id":' + '"' + event_list[i].sys_id.value + '",' +
                '"start":' + '"' + start + '",' +
                '"startMS":' + startTime + ',' +
                '"title":' + '"' + event_list[i].u_kenmei.value + '"' + "}";
            if (i == event_list.length - 1) {
                str += "]";
            } else {
                str += ",";
            }
        }
        //ログインユーザーと予定情報が一致する場合
        if ((user_login_name == event_list[i].u_kanren_shien_taishosha.displayValue)) {
            if (event_list[i].u_karitouroku.displayValue == "true") {
                var bgColor = "nds-gray";
            } else {
                //背景色をつけて
                var bgColor = "nds-blue";
            }

            if (event_list[i].u_yotei_shubetsu.value == 1) {
                var bgColor = "nds-orange";
            }

            //内容欄を設定
            var description = "参加者:" + event_list[i].u_kanren_shien_taishosha.displayValue;
            //予定情報の開始時間
            var start = event_list[i].u_kaishibi.value + " " + event_list[i].u_kaishi_jikan.value;
            //予定情報の終了時間
            var end = event_list[i].u_shuryobi.value + " " + event_list[i].u_shuryo_jikan.value;
            //予定情報の開始時間変換
            var startTime = dateTimeStringToTimestamp(start);
            //予定情報の終了時間変換
            var endTime = dateTimeStringToTimestamp(end);

            if (event_list[i].u_yotei_shubetsu.value == 1) {
                var group = "groupIT";
            } else {
                var group = "login_in";
            }
            //Json情報を組み合わせ
            str += '{' + '"bgColor":' + '"' + bgColor + '",' +
                '"description":' + '"' + description + '",' +
                '"end":' + '"' + end + '",' +
                '"endMS":' + endTime + ',' +
                '"group":' + '"' + group + '",' +
                '"id":' + '"' + event_list[i].sys_id.value + '",' +
                '"start":' + '"' + start + '",' +
                '"startMS":' + startTime + ',' +
                '"title":' + '"' + event_list[i].u_kenmei.value + '"' + "}";
            if (i == event_list.length - 1) {
                str += "]";
            } else {
                str += ",";
            }
        }

    }
    //JSON 文字列の最後がカンマで終わっている場合は修正
    if (str !== "[") {
        if (str.trim().endsWith(',')) {
            str = str.trim().slice(0, -1);
            str += "]";
        }
        //検索欄が空で、ログイン中ユーザーの予定だけ表示
    } else {
        var event_list = api.data.look_up_multiple_records_1.results;
        var str = "[";
        for (var i = 0; i < event_list.length; i++) {
            if (user_login_name == event_list[i].u_kanren_shien_taishosha.displayValue) {
                if (event_list[i].u_karitouroku.displayValue == "true") {
                    var bgColor = "nds-gray";
                } else {
                    //背景色をつけて
                    var bgColor = "nds-blue";
                }

                if (event_list[i].u_yotei_shubetsu.value == 1) {
                    var bgColor = "nds-orange";
                }

                if (event_list[i].u_yotei_shubetsu.value == 1) {
                    var group = "groupIT";
                } else {
                    var group = "login_in";
                }
                //内容欄を設定
                var description = "参加者:" + event_list[i].u_kanren_shien_taishosha.displayValue;
                //予定情報の開始時間
                var start = event_list[i].u_kaishibi.value + " " + event_list[i].u_kaishi_jikan.value;
                //予定情報の終了時間
                var end = event_list[i].u_shuryobi.value + " " + event_list[i].u_shuryo_jikan.value;
                //予定情報の開始時間変換
                var startTime = dateTimeStringToTimestamp(start);
                //予定情報の終了時間変換
                var endTime = dateTimeStringToTimestamp(end);
                //Json情報を組み合わせ
                str += '{' + '"bgColor":' + '"' + bgColor + '",' +
                    '"description":' + '"' + description + '",' +
                    '"end":' + '"' + end + '",' +
                    '"endMS":' + endTime + ',' +
                    '"group":' + '"' + group + '",' +
                    '"id":' + '"' + event_list[i].sys_id.value + '",' +
                    '"start":' + '"' + start + '",' +
                    '"startMS":' + startTime + ',' +
                    '"title":' + '"' + event_list[i].u_kenmei.value + '"' + "}";
                if (i == event_list.length - 1) {
                    str += "]";
                } else {
                    str += ",";
                }
            }
        }
        console.log("event_data:", str);
        //JSON 文字列の最後がカンマで終わっている場合は修正
        if (str.trim().endsWith(',')) {
            str = str.trim().slice(0, -1);
            str += "]";
        }
    }
    console.log("Event data:", str);
    api.setState("event_data", str);
}
